#include <iostream>
#include <string>
#include <vector>

struct Student {
    std::string name;
    int gender; // 1: Nam (Male), 0: Nu (Female)
    double gpa;
};

int main() {
    Student s1{"Nguyen Van A", 1, 8.5};
    Student* ptr = &s1;

    // Cach 1: p->field
    ptr->gpa = 9.0;
    // Cach 2: (*p).field
    (*ptr).gender = 1;

    std::cout << "Cach 1 (ptr->name): " << ptr->name << "\n";
    std::cout << "Cach 2 ((*ptr).gpa): " << (*ptr).gpa << "\n";

    // Mang dong va con tro
    std::vector<Student> classList = {
        {"Tran Van B", 1, 7.5},
        {"Le Thi C", 0, 8.8}
    };
    Student* pArr = classList.data();

    // 3 cach truy cap phan tu thu 1
    std::cout << "pArr[1].name: " << pArr[1].name << "\n";
    std::cout << "(pArr + 1)->gpa: " << (pArr + 1)->gpa << "\n";
    std::cout << "(*(pArr + 1)).gender: " << (*(pArr + 1)).gender << "\n";

    return 0;
}

#include <iostream>

struct Date {
    int day;
    int month;
    int year;
};

// Ham kiem tra nam nhuan
int isLeapYear(int year) {
    return ((year % 4 == 0 && year % 100 != 0) || (year % 400 == 0)) ? 1 : 0;
}

// So ngay trong thang
int daysInMonth(int month, int year) {
    const int daysPerMonth[13] = {0, 31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};
    return daysPerMonth[month] + ((month == 2) ? isLeapYear(year) : 0);
}

// Truyen tham chieu de in va lay dia chi
void printDateInfo(const Date& d) {
    std::cout << "Ngay: " << d.day << "/" << d.month << "/" << d.year << "\n";
    std::cout << "So ngay cua thang: " << daysInMonth(d.month, d.year) << "\n";
}

int main() {
    Date d1{28, 2, 2024};

    // Lay dia chi cua tung truong thanh phan
    int* pYear = &d1.year;
    std::cout << "Nam tu con tro &d1.year: " << *pYear << "\n";

    printDateInfo(d1);
    return 0;
}
